+package com.example;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+            "^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final MessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messagesGrid = new Grid<>();
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        addClassName("contact-view");
+        setPadding(true);
+        setSpacing(true);
+        setMaxWidth("72rem");
+        getStyle().set("margin", "0 auto");
+
+        H1 heading = new H1("Contact");
+        heading.addClassName("contact-heading");
+
+        RouterLink aboutLink = new RouterLink("About", AboutView.class);
+        aboutLink.addClassName("about-link");
+
+        FormLayout form = buildForm();
+        HorizontalLayout actions = new HorizontalLayout(send);
+        actions.addClassName("contact-actions");
+
+        VerticalLayout composer = new VerticalLayout(form, actions);
+        composer.addClassName("contact-composer");
+        composer.setPadding(true);
+        composer.setSpacing(true);
+        composer.setWidthFull();
+
+        configureGrid();
+
+        Span listHeading = new Span("Messages sent");
+        listHeading.addClassName("messages-heading");
+
+        add(heading, aboutLink, composer, listHeading, messagesGrid);
+        setAlignItems(Alignment.STRETCH);
+    }
+
+    private FormLayout buildForm() {
+        name.setRequiredIndicatorVisible(true);
+        email.setManualValidation(true);
+        phone.setRequiredIndicatorVisible(false);
+        message.setRequiredIndicatorVisible(true);
+        message.setMinRows(5);
+        message.setHelperText("Up to 500 characters");
+
+        FormLayout form = new FormLayout();
+        form.addClassName("contact-form");
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setColumnSpacing("var(--vaadin-gap-m)");
+        form.setRowSpacing("var(--vaadin-gap-s)");
+        form.addFormRow(name, email);
+        form.addFormRow(phone);
+        form.add(message);
+
+        send.addThemeVariants(com.vaadin.flow.component.button.ButtonVariant.PRIMARY);
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> fieldEdited(name));
+        email.addValueChangeListener(event -> fieldEdited(email));
+        phone.addValueChangeListener(event -> fieldEdited(phone));
+        message.addValueChangeListener(event -> fieldEdited(message));
+
+        return form;
+    }
+
+    private void configureGrid() {
+        messagesGrid.addClassName("messages-grid");
+        messagesGrid.setWidthFull();
+        messagesGrid.setAllRowsVisible(true);
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name");
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message");
+        messagesGrid.setItems(messageStore.getMessages());
+    }
+
+    private void fieldEdited(HasValidation field) {
+        send.setEnabled(true);
+        field.setInvalid(false);
+    }
+
+    private void submit() {
+        clearValidation();
+
+        String nameValue = name.getValue();
+        String emailValue = email.getValue();
+        String phoneValue = phone.getValue();
+        String messageValue = message.getValue();
+
+        boolean valid = true;
+
+        if (isBlank(nameValue)) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+
+        boolean emailGiven = !isBlank(emailValue);
+        boolean phoneGiven = !isBlank(phoneValue);
+        if (emailGiven && !EMAIL_PATTERN.matcher(emailValue.trim()).matches()) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (!emailGiven && !phoneGiven) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (isBlank(messageValue)) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            markInvalid(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(nameValue, emailValue, phoneValue, messageValue));
+        messagesGrid.setItems(messageStore.getMessages());
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private static void markInvalid(TextField field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private static void markInvalid(EmailField field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private static void markInvalid(TextArea field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private static boolean isBlank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.addClassName("leave-dialog");
+        dialog.setHeaderTitle("Leave contact form?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Paragraph prompt = new Paragraph("You have an unsent message. What would you like to do?");
+        Button keepEditing = new Button("Keep editing", click -> {
+            dialog.close();
+            action.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(com.vaadin.flow.component.button.ButtonVariant.PRIMARY);
+
+        HorizontalLayout actions = new HorizontalLayout(keepEditing, discard);
+        actions.addClassName("leave-dialog-actions");
+        dialog.add(prompt, actions);
+        dialog.open();
+    }
+
+    private boolean hasUnsavedInput() {
+        return !isBlank(name.getValue()) || !isBlank(email.getValue())
+                || !isBlank(phone.getValue()) || !isBlank(message.getValue());
+    }
+}
