+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps submitted messages for the lifetime of the application.
+ *
+ * There is deliberately no persistence requirement for this application, but
+ * keeping the store as a Spring service means route changes do not lose rows.
+ */
+@Service
+public class MessageStore {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public synchronized List<ContactMessage> getMessages() {
+        return List.copyOf(messages);
+    }
+}
